// ১. সুইচ কন্ট্রোল এবং আপনার মাস্টার লজিক
final android.widget.Switch sw1 = findViewById(R.id.switch1);
final android.widget.Switch sw2 = findViewById(R.id.switch2);

sw1.setOnCheckedChangeListener((btn, isChecked) -> {
    if (isChecked) {
        android.content.Intent vpnIntent = android.net.VpnService.prepare(this);
        if (vpnIntent != null) startActivityForResult(vpnIntent, 0);
        else onActivityResult(0, RESULT_OK, null);
    } else {
        android.content.Intent it = new android.content.Intent(this, CycleService.class);
        it.setAction("STOP");
        startService(it);
    }
});

sw2.setOnCheckedChangeListener((btn, isChecked) -> {
    if (isChecked) {
        String pkg = "com.opendeta.android.apps.systemadblocker";
        String currentVpn = android.provider.Settings.Secure.getString(getContentResolver(), "always_on_vpn_app");
        if (pkg.equals(currentVpn)) {
            sw1.setChecked(true); // Always-on থাকলে সার্ভিস স্টার্ট হবে
        } else {
            try {
                android.content.Intent it = new android.content.Intent("android.net.vpn.SETTINGS");
                startActivity(it);
                sw2.setChecked(false);
                android.widget.Toast.makeText(getApplicationContext(), "Select SnapBlocker & enable Always-on", 1).show();
            } catch (Exception e) {}
        }
    }
});

} // onCreate closed

@Override
protected void onActivityResult(int requestCode, int resultCode, android.content.Intent data) {
    if (requestCode == 0 && resultCode == RESULT_OK) {
        android.content.Intent it = new android.content.Intent(this, CycleService.class);
        it.setAction("START");
        startService(it);
    }
}

public static class CycleService extends android.net.VpnService {
    private android.os.ParcelFileDescriptor vpnInterface = null;
    private static final String CHANNEL_ID = "snap_blocker_pro";

    @Override
    public int onStartCommand(android.content.Intent intent, int flags, int startId) {
        String action = (intent != null) ? intent.getAction() : "";

        if ("STOP".equals(action)) {
            stopVpn();
            showNotification(false);
            return START_NOT_STICKY;
        }

        establishVpn();
        showNotification(true);
        return START_STICKY;
    }

    private void establishVpn() {
        try {
            if (vpnInterface == null) {
                vpnInterface = new Builder()
                    .setSession("SnapBlocker")
                    .addAddress("10.0.0.2", 32)
                    .addDnsServer("94.140.14.14") 
                    .addDnsServer("94.140.15.15")
                    .addRoute("10.0.0.3", 32) // আপনার দেওয়া সেই জাদুকরী ডামি রুট
                    .setConfigureIntent(android.app.PendingIntent.getActivity(this, 0, new android.content.Intent(this, MainActivity.class), android.app.PendingIntent.FLAG_IMMUTABLE))
                    .establish();
            }
        } catch (Exception e) {}
    }

    private void showNotification(boolean active) {
        if (android.os.Build.VERSION.SDK_INT >= 26) {
            android.app.NotificationChannel ch = new android.app.NotificationChannel(CHANNEL_ID, "SnapPro", android.app.NotificationManager.IMPORTANCE_LOW);
            getSystemService(android.app.NotificationManager.class).createNotificationChannel(ch);
        }

        android.content.Intent it = new android.content.Intent(this, CycleService.class);
        it.setAction(active ? "STOP" : "START");
        android.app.PendingIntent pi = android.app.PendingIntent.getService(this, 0, it, android.app.PendingIntent.FLAG_UPDATE_CURRENT | android.app.PendingIntent.FLAG_IMMUTABLE);

        android.app.Notification notification = new android.app.Notification.Builder(this, CHANNEL_ID)
                .setContentTitle(active ? "Blocking Ads…" : "Block All Ads on Your Phone")
                .setContentText(active ? "ইন্টারনেট সুপারফাস্ট, অ্যাড ব্লক সিস্টেম-ওয়াইড!" : "অ্যাড ব্লক করতে Start চাপুন")
                .setSmallIcon(android.R.drawable.ic_secure)
                .setOngoing(true)
                .addAction(new android.app.Notification.Action.Builder(null, active ? "Stop" : "Start", pi).build())
                .build();

        startForeground(1, notification);
    }

    private void stopVpn() {
        try { if(vpnInterface != null) { vpnInterface.close(); vpnInterface = null; } } catch (Exception e) {}
        stopForeground(true);
    }

    @Override
    public void onDestroy() {
        stopVpn();
        super.onDestroy();
    }
}
